const vm = require('vm');
const fs = require('fs');
const path = require('path');

// Lambda handler for dynamic report generation
// Supports template expressions like ${user.name} in report configs
exports.handler = async (event) => {
  try {
    const { templateId, parameters, userContext } = JSON.parse(event.body || '{}');

    if (!templateId || !parameters) {
      return { statusCode: 400, body: JSON.stringify({ error: 'Missing templateId or parameters' }) };
    }

    // Load template from local config directory
    const templatePath = path.join('/var/task/templates', `${templateId}.json`);
    let templateConfig;
    try {
      templateConfig = JSON.parse(fs.readFileSync(templatePath, 'utf8'));
    } catch (e) {
      return { statusCode: 404, body: JSON.stringify({ error: 'Template not found' }) };
    }

    // Resolve dynamic expressions in template fields
    const resolved = resolveExpressions(templateConfig, parameters, userContext);

    return {
      statusCode: 200,
      body: JSON.stringify({ report: resolved, generatedAt: new Date().toISOString() })
    };
  } catch (err) {
    console.error('Handler error:', err.message);
    return { statusCode: 500, body: JSON.stringify({ error: 'Internal error' }) };
  }
};

function resolveExpressions(template, params, context) {
  const result = {};
  const sandbox = {
    params: params,
    context: context || {},
    Math: Math,
    Date: Date,
    parseInt: parseInt,
    parseFloat: parseFloat
  };

  for (const [key, value] of Object.entries(template.fields || {})) {
    if (typeof value === 'string' && value.startsWith('${') && value.endsWith('}')) {
      // Extract expression from ${...} wrapper
      const expr = value.slice(2, -1);
      try {
        // Evaluate expression in sandboxed context
        const script = new vm.Script(expr);
        const vmContext = vm.createContext(sandbox);
        result[key] = script.runInContext(vmContext, { timeout: 1000 });
      } catch (evalErr) {
        result[key] = `[Error: ${evalErr.message}]`;
      }
    } else {
      result[key] = value;
    }
  }
  return result;
}

// Health check endpoint
exports.health = async () => {
  return {
    statusCode: 200,
    body: JSON.stringify({
      status: 'healthy',
      runtime: process.version,
      cwd: process.cwd()
    })
  };
};

// Utility: validate template structure before saving
exports.validateTemplate = async (event) => {
  const { fields } = JSON.parse(event.body || '{}');
  if (!fields || typeof fields !== 'object') {
    return { statusCode: 400, body: JSON.stringify({ error: 'Invalid template structure' }) };
  }

  const expressionPattern = /^\$\{[^}]+\}$/;
  const warnings = [];

  for (const [key, value] of Object.entries(fields)) {
    if (typeof value === 'string' && value.includes('${') && !expressionPattern.test(value)) {
      warnings.push(`Field '${key}' has malformed expression`);
    }
  }

  return {
    statusCode: 200,
    body: JSON.stringify({ valid: true, warnings })
  };
};
